<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_login();$subject=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT);$grade=(int)user()['grade_id'];$medium=(string)user()['medium'];$sql="SELECT p.*,s.name_en,s.name_si,s.name_ta,(SELECT COUNT(*) FROM paper_questions q WHERE q.paper_id=p.id) question_count,(SELECT COALESCE(SUM(marks),0) FROM paper_questions q WHERE q.paper_id=p.id) allocated FROM practice_papers p JOIN subjects s ON s.id=p.subject_id WHERE p.grade_id=? AND p.medium=? AND p.status='active'";$types='is';$args=[$grade,$medium];if($subject){$sql.=' AND p.subject_id=?';$types.='i';$args[]=$subject;}$sql.=' ORDER BY p.created_at DESC,p.id DESC';$s=db()->prepare($sql);$s->bind_param($types,...$args);$s->execute();$papers=$s->get_result();$pageTitle='Past Papers';include __DIR__.'/../includes/header.php';?>
<section class="card" style="background:linear-gradient(135deg,#30247e,#6554e8 55%,#168dbf);color:#fff"><span class="badge">Grade <?=user_grade_number()?> · <?=e($medium)?></span><h1>📄 Paper Practice</h1><p style="color:#dcd9ff">Practise complete papers with MCQs, structured questions, model answers and official mark allocations.</p></section><?php if(!$papers->num_rows):?><section class="card"><p>No imported papers are available for this selection yet.</p></section><?php endif;?><section class="grid"><?php while($p=$papers->fetch_assoc()):?><article class="card"><span class="badge"><?=e(locale_value($p,'name'))?></span><h2><?=e($p['title'])?></h2><p><strong><?=intval($p['question_count'])?> questions</strong> · <?=e($p['allocated'])?> / <?=intval($p['total_marks'])?> marks<?php if($p['duration_minutes']):?> · <?=intval($p['duration_minutes'])?> min<?php endif;?></p><a class="btn" href="paper.php?id=<?=intval($p['id'])?>">Open full paper</a></article><?php endwhile;?></section><?php include __DIR__.'/../includes/footer.php';
